import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"docs-editor/keyboard-shortcuts.md","filePath":"docs-editor/keyboard-shortcuts.md"}'),o={name:"docs-editor/keyboard-shortcuts.md"};function n(i,t,l,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Keyboard shortcuts for the document editor. Mac shortcuts are shown with <code>⌘</code>, Windows/Linux with <code>Ctrl</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Press <strong>⌘+/</strong> / <strong>Ctrl+/</strong> inside the editor to see this list in a dialog. The dialog is maintained alongside the editor&#39;s bindings rather than derived from them, but it currently matches this page entry for entry.</p></div><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Move cursor</td><td>Arrow keys</td><td>Arrow keys</td></tr><tr><td>Move by word</td><td>⌥+← / ⌥+→</td><td>Ctrl+← / Ctrl+→</td></tr><tr><td>Move to line start</td><td>⌘+← or Home</td><td>Home</td></tr><tr><td>Move to line end</td><td>⌘+→ or End</td><td>End</td></tr><tr><td>Move to document start</td><td>⌘+↑ or ⌘+Home</td><td>Ctrl+Home</td></tr><tr><td>Move to document end</td><td>⌘+↓ or ⌘+End</td><td>Ctrl+End</td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Extend selection</td><td>Shift+Arrow</td><td>Shift+Arrow</td></tr><tr><td>Select by word</td><td>⌥+Shift+← / →</td><td>Ctrl+Shift+← / →</td></tr><tr><td>Select to line start</td><td>⌘+Shift+← or Shift+Home</td><td>Shift+Home</td></tr><tr><td>Select to line end</td><td>⌘+Shift+→ or Shift+End</td><td>Shift+End</td></tr><tr><td>Select to document start</td><td>⌘+Shift+↑ or ⌘+Shift+Home</td><td>Ctrl+Shift+Home</td></tr><tr><td>Select to document end</td><td>⌘+Shift+↓ or ⌘+Shift+End</td><td>Ctrl+Shift+End</td></tr><tr><td>Select all</td><td>⌘+A</td><td>Ctrl+A</td></tr><tr><td>Select word</td><td>Double-click</td><td>Double-click</td></tr><tr><td>Select paragraph</td><td>Triple-click</td><td>Triple-click</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>New paragraph</td><td>Enter</td><td>Enter</td></tr><tr><td>Page break</td><td>⌘+Enter</td><td>Ctrl+Enter</td></tr><tr><td>Delete character before</td><td>Backspace</td><td>Backspace</td></tr><tr><td>Delete character after</td><td>Delete</td><td>Delete</td></tr><tr><td>Delete word before</td><td>⌥+Backspace</td><td>Ctrl+Backspace</td></tr><tr><td>Delete word after</td><td>⌥+Delete</td><td>Ctrl+Delete</td></tr><tr><td>Delete to line start</td><td>⌘+Backspace</td><td>—</td></tr><tr><td>Undo</td><td>⌘+Z</td><td>Ctrl+Z</td></tr><tr><td>Redo</td><td>⌘+Shift+Z</td><td>Ctrl+Y</td></tr></tbody></table><h2 id="clipboard" tabindex="-1">Clipboard <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Clipboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Copy</td><td>⌘+C</td><td>Ctrl+C</td></tr><tr><td>Cut</td><td>⌘+X</td><td>Ctrl+X</td></tr><tr><td>Paste</td><td>⌘+V</td><td>Ctrl+V</td></tr><tr><td>Paste without formatting</td><td>⌘+Shift+V</td><td>Ctrl+Shift+V</td></tr><tr><td>Copy formatting (format painter)</td><td>⌘+Shift+C</td><td>Ctrl+Shift+C</td></tr><tr><td>Paste formatting</td><td>⌘+Alt+V</td><td>Ctrl+Alt+V</td></tr></tbody></table><h2 id="text-formatting" tabindex="-1">Text Formatting <a class="header-anchor" href="#text-formatting" aria-label="Permalink to &quot;Text Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Bold</td><td>⌘+B</td><td>Ctrl+B</td></tr><tr><td>Italic</td><td>⌘+I</td><td>Ctrl+I</td></tr><tr><td>Underline</td><td>⌘+U</td><td>Ctrl+U</td></tr><tr><td>Strikethrough</td><td>⌘+Shift+X</td><td>Ctrl+Shift+X</td></tr><tr><td>Superscript</td><td>⌘+.</td><td>Ctrl+.</td></tr><tr><td>Subscript</td><td>⌘+,</td><td>Ctrl+,</td></tr><tr><td>Insert link</td><td>⌘+K</td><td>Ctrl+K</td></tr><tr><td>Clear formatting</td><td>⌘+\\</td><td>Ctrl+\\</td></tr></tbody></table><h2 id="paragraph-formatting" tabindex="-1">Paragraph Formatting <a class="header-anchor" href="#paragraph-formatting" aria-label="Permalink to &quot;Paragraph Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Align left</td><td>⌘+Shift+L</td><td>Ctrl+Shift+L</td></tr><tr><td>Align center</td><td>⌘+Shift+E</td><td>Ctrl+Shift+E</td></tr><tr><td>Align right</td><td>⌘+Shift+R</td><td>Ctrl+Shift+R</td></tr><tr><td>Justify</td><td>⌘+Shift+J</td><td>Ctrl+Shift+J</td></tr><tr><td>Numbered list</td><td>⌘+Shift+7</td><td>Ctrl+Shift+7</td></tr><tr><td>Bulleted list</td><td>⌘+Shift+8</td><td>Ctrl+Shift+8</td></tr><tr><td>Increase indent</td><td>⌘+]</td><td>Ctrl+]</td></tr><tr><td>Decrease indent</td><td>⌘+[</td><td>Ctrl+[</td></tr><tr><td>Heading 1 – 6</td><td>⌘+Alt+1 … ⌘+Alt+6</td><td>Ctrl+Alt+1 … Ctrl+Alt+6</td></tr><tr><td>Normal text</td><td>⌘+Alt+0</td><td>Ctrl+Alt+0</td></tr></tbody></table><p>Applying the heading level a block already has toggles it back to Normal text.</p><h2 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h2><p><strong>Tab</strong> does different things depending on where the cursor is:</p><table tabindex="0"><thead><tr><th>Where</th><th>Tab</th><th>Shift+Tab</th></tr></thead><tbody><tr><td>In a table cell</td><td>Move to the next cell</td><td>Move to the previous cell</td></tr><tr><td>In a list item</td><td>Nest one level deeper</td><td>Move out one level</td></tr><tr><td>Anywhere else</td><td>Nothing</td><td>Nothing</td></tr></tbody></table><p>For indenting a plain paragraph, use <strong>⌘+]</strong> / <strong>Ctrl+]</strong> instead.</p><h2 id="find-comments-and-help" tabindex="-1">Find, Comments, and Help <a class="header-anchor" href="#find-comments-and-help" aria-label="Permalink to &quot;Find, Comments, and Help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Mac</th><th>Windows / Linux</th></tr></thead><tbody><tr><td>Find</td><td>⌘+F</td><td>Ctrl+F</td></tr><tr><td>Find and replace</td><td>⌘+H</td><td>Ctrl+H</td></tr><tr><td>Insert comment on the selection</td><td>⌘+Option+M</td><td>Ctrl+Alt+M</td></tr><tr><td>Open / close the comments panel</td><td>⌘+Option+Shift+M</td><td>Ctrl+Alt+Shift+M</td></tr><tr><td>Show keyboard shortcuts</td><td>⌘+/</td><td>Ctrl+/</td></tr></tbody></table><h2 id="read-only-documents" tabindex="-1">Read-Only Documents <a class="header-anchor" href="#read-only-documents" aria-label="Permalink to &quot;Read-Only Documents&quot;">​</a></h2><p>When you open a document you can only read — through a viewer share link, for example — most shortcuts are switched off so the content can&#39;t be changed. What still works:</p><ul><li>Arrow keys, <strong>Home</strong>, and <strong>End</strong> for moving the cursor</li><li><strong>⌘+A</strong> / <strong>Ctrl+A</strong> to select all</li><li><strong>⌘+C</strong> / <strong>Ctrl+C</strong> to copy</li><li><strong>⌘+F</strong> / <strong>Ctrl+F</strong> to find</li><li><strong>⌘+/</strong> / <strong>Ctrl+/</strong> to open the shortcuts dialog</li><li><strong>⌘+Option+Shift+M</strong> / <strong>Ctrl+Alt+Shift+M</strong> to open and close the comments panel — you can read the existing threads, though not reply to them or start a new one</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="./writing-a-document.html">Writing a Document</a> — Full guide to the document editor</li><li><a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a> — Share and edit documents together</li></ul>',27)])])}const u=d(o,[["render",n]]);export{g as __pageData,u as default};
